with with_dims as (select e.*, b.budget, b.dept_name, b.location from employees e inner join departments b on e.dept_id = b.id), with_dims_employees as (select src.id, src.email, src.manager_id, src.job_title, src.salary, src.is_remote, src.level, src.budget, src.dept_name, src.location, d.email as employee_email, d.hire_date as employee_hire_date, d.level as employee_level from with_dims src inner join employees d on src.manager_id <=> d.id), with_dims_employees_2 as (select a.id, a.manager_id, a.salary, a.is_remote, a.location, a.employee_email, a.employee_hire_date, d.full_name, d.level as employee_level_2 from with_dims_employees a left join employees d on a.manager_id = d.id), with_dims_employees_3 as (select a.*, e.full_name as employee_full_name, e.salary as employee_salary, e.job_title from with_dims_employees_2 a left join employees e on a.manager_id <=> e.id), with_dims_employees_4 as (select a.id, a.manager_id, a.salary, a.employee_email, a.employee_hire_date, a.employee_level_2, a.employee_full_name, a.employee_salary, a.job_title, b.level, b.job_title as employee_job_title, b.hire_date from with_dims_employees_3 a inner join employees b on a.manager_id = b.id), with_dims_employees_5 as (select e.*, p2.full_name, p2.email from with_dims_employees_4 e left join employees p2 on e.manager_id = p2.id) select * from (select employee_job_title, level, job_title, salary from with_dims_employees_5) src pivot (max(salary) as value_sum, count(1) as item_count for job_title in ('Analyst' as analyst, 'Engineer' as engineer));
